const path = require("path");
const ROOT = path.resolve("/app/uploads"); // simulate absolute canonical root
const sep = path.sep;
console.log("ROOT =", JSON.stringify(ROOT), "sep =", JSON.stringify(sep));

const cases = [
  "foo.txt",
  "../etc/passwd",
  "../../etc/passwd",
  "../../../etc/passwd",
  "/etc/passwd",                 // absolute input
  "/app/uploads-secret/secret", // sibling-dir prefix confusion
  "",
  ".",
  "./",
  "..",
  "public/readme.txt",
  "a/../../../etc/passwd",
  "/app/uploads/../../../etc/passwd", // absolute but with traversal
];

for (const name of cases) {
  const candidate = path.resolve(ROOT, name);
  const allowed = !(candidate === ROOT || !candidate.startsWith(ROOT + sep));
  console.log(JSON.stringify(name).padEnd(42), "->", JSON.stringify(candidate), allowed ? "ALLOWED" : "BLOCKED");
}
